import React from 'react';

import { Link } from 'react-router-dom';

import { getFundsAsync } from '@apps/Finances/@services/funds.service';
import { IFundsListCriteria } from '@apps/Finances/@types/funds.dto.types';
import { IFund } from '@apps/Finances/@types/funds.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohList, { IPohListProps } from '@ui-kit/List';

import FundListItem from './FundListItem';

interface IFundsListProps extends Omit<IPohListProps, 'onSelect' | 'data'> {
  criteria?: IFundsListCriteria;
  onSelect?: (selected: IFund) => void;
  toolbar?: (fund: IFund) => React.ReactNode;
}

const FundsList: React.FC<IFundsListProps> = ({ onSelect, criteria, toolbar, ...rest }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IFund[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const d = await getFundsAsync(criteria);
        setData(d);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [criteria]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data.length) return <Empty>Нет фондов</Empty>;

  return (
    <PohList
      {...rest}
      data={data.map((d) => {
        return {
          key: d.id,
          onClick: onSelect ? () => onSelect(d) : () => {},
          action: true,
          as: !onSelect ? Link : undefined,
          to: `/finances/funds/${d.id}`,
          children: <FundListItem fund={d} toolbar={toolbar} />,
        };
      })}
    />
  );
};

export default FundsList;
